css:
.loader { --accent: var(--loader-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader span { position: absolute; inset: 0; border: calc(var(--loader-size) * .04) solid var(--accent); border-radius: 50%; opacity: 0; animation: sonar calc(var(--loader-speed) * 2) ease-out infinite; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .66); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * 1.33); }
@keyframes sonar { 0% { transform: scale(.1); opacity: 1; } 100% { transform: scale(1); opacity: 0; } }
